/*
 * A183080  Tree generated by the Beatty sequence of 3-sqrt(2).
 * https://oeis.org/A183080
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 8, u16 n <= 34, u32 n <= 2431, u64 n <= 8192,
 *            u128 n <= 8192, big any n
 * Helpers:   seq_alloc_array, seq_free_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A183080: tree generated by Beatty sequence of 3‑sqrt(2).
   The code builds the tree level by level and returns the nth term
   in breadth‑first order, using only integer arithmetic. */

#include <stddef.h>
#include <stdlib.h>
#include "../utils/seq_alloc_array.h"
#include "../utils/seq_free_array.h"

/* integer square root of a non‑negative seq_t value x.
   Returns floor(sqrt(x)). */
static inline seq_t isqrt_seq(seq_t x)
{
    seq_t lo = 0;
    seq_t hi = x;
    while (lo < hi)
    {
        seq_t mid = (lo + hi + (seq_t)1) / 2;
        seq_t sq = mid * mid;
        if (sq <= x)
            lo = mid;
        else
            hi = mid - (seq_t)1;
    }
    return lo;
}

/* floor(n * sqrt(2)) for n expressed as seq_t.
   Uses the identity floor(n*sqrt(2)) = floor(sqrt(2*n*n)). */
static inline seq_t floor_nsqrt2(seq_t n)
{
    if (n == (seq_t)0)
        return (seq_t)0;
    seq_t prod = n * n;
    prod = prod * ((seq_t)2);
    return isqrt_seq(prod);
}

/* L(n) = ⌊n·(3-√2)⌋ = 3n - floor(n·√2) - 1 */
static inline seq_t L_val(seq_t n)
{
    seq_t t = floor_nsqrt2(n);
    return (n * ((seq_t)3)) - t - ((seq_t)1);
}

/* U(n) = ⌊n·(2+√2/2)⌋ = 2n + floor(floor(n·√2)/2) */
static inline seq_t U_val(seq_t n)
{
    seq_t t = floor_nsqrt2(n);
    return (n * ((seq_t)2)) + (t / ((seq_t)2));
}

/* --------------------------------------------------------------------- */
/*  Main routine: nth term of A183080   (1‑based index)                 */
seq_t a(idx_t n)
{
    if (n == (idx_t)1)
        return (seq_t)1;
    if (n == (idx_t)2)
        return (seq_t)2;

    /* Allocate an array big enough for the first n terms. */
    seq_t *seq = seq_alloc_array(n);
    if (!seq)
        return (seq_t)0; /* allocation failed */

    seq[0] = (seq_t)1;
    seq[1] = (seq_t)2;

    size_t pos = 2;          /* next free slot in seq */
    size_t row_start = 1;    /* start index of the current row (row 1) */
    size_t row_len   = 1;    /* number of elements in the current row */

    while (pos < n)
    {
        for (size_t j = 0; j < row_len && pos < n; ++j)
        {
            seq_t v = seq[row_start + j];
            seq[pos++] = L_val(v);
            if (pos >= n)
                break;
            seq[pos++] = U_val(v);
        }
        row_start += row_len;
        row_len <<= 1;
    }

    seq_t result = seq[n - 1];
    seq_free_array(seq);
    return result;
}
